# November 19, 2026: Logan County, Oklahoma (Guthrie, Langston, Mulhall, Marshall). First batch in Oklahoma beyond the worked example.
# Facts from the linked sources only: Wikipedia read with wiki_raw.py, National Register forms read as text from NPGallery,
# the Oklahoma Historical Society's pages, the City of Guthrie's cemetery page, the museums' and theatre's own pages,
# an HMdb marker and two Waymarking pages (named in the access notes where they are the only source for a detail).
from data_b import N
from data_ma import W
NR='https://npgallery.nps.gov/NRHP/GetAsset/NRHP/'
def F(ref,label='National Register form'): return [label,NR+ref+'_text']
BATCH={'key':'ok_rbbg','label':'Logan County, Oklahoma','added':'2026-11-19 19:52'}
PLACES=[
N('carnegie-library-guthrie','Carnegie Library and Oklahoma Territorial Museum','Guthrie','ok','civic','standing',35.87832,-97.42126,'exact','open','drive','','1901–1903',
  'A domed brick and stone library, its cornerstone laid in October 1901 and opened in 1903 with Andrew Carnegie\'s money: the 1971 Register form calls it present-day Oklahoma\'s first Carnegie library, Wikipedia the second built in the state and the oldest still standing. Statehood ceremonies were held on its steps on November 16, 1907. In 1972 the city planned to tear it down; Fred Pfeiffer paid for a new library next door if the old one was kept, and the Oklahoma Historical Society opened a museum beside it in 1973. The two buildings are now joined as one museum.',
  'The two-story Second Renaissance Revival library, of tan brick with stone trim and Ionic columns in a 2006 photograph, with its dome, about 20 feet across and some 50 feet above the foyer (Register form), and the steps where statehood was celebrated. Inside, the museum tells the territorial story with artifacts, photographs and paintings. What original fittings survive inside the library was not checked.',
  'The library steps where Oklahoma became a state.',
  'Run by the Oklahoma Historical Society, 406 East Oklahoma Avenue. Its page read on November 19, 2026 gave no opening days, only a Thanksgiving closing (November 26 and 27); check the society\'s page before going. Street parking downtown, not checked.',
  [W('Carnegie Library (Guthrie, Oklahoma)'),['Oklahoma Historical Society: the museum','https://okhistory.org/sites/territorialmuseum'],F('71000666')],brick='no',hours='?'),
N('logan-county-courthouse-guthrie','Logan County Courthouse','Guthrie','ok','civic','standing',35.87671,-97.42247,'exact','view','drive','','1907',
  'The county courthouse at 301 East Harrison, built in 1907 to a design by P. H. Weathers. It stands apart from the rest of the Guthrie Historic District but is counted in it, and it was listed on the National Register on its own in 1984.',
  'A four-story buff brick building, simplified Beaux Arts with Classical Revival detail. Interior not checked.',
  '','A working county courthouse. Look from the street; when the building is open to the public was not checked.',
  [W('Logan County Courthouse (Oklahoma)'),W('Guthrie Historic District (Guthrie, Oklahoma)')],brick='no'),
N('scottish-rite-temple-guthrie','Scottish Rite Temple (Guthrie)','Guthrie','ok','civic','standing',35.87807,-97.41351,'exact','open','drive','','1908',
  'The city built a brick Convention Hall here in 1908 for the new state legislature, which met in it for one regular session in 1909 and a special one in 1910 before the capital went to Oklahoma City. The city then sold the hall and Capitol Park round it to the Scottish Rite Masons, who began a great limestone temple to the west in May 1920 and were using it from 1923; the hall is now its East Annex. The Register form calls it the largest and most elaborate Masonic temple in Oklahoma.',
  'A Neo-classical temple of Indiana limestone over a concrete frame, joined by a brick and stone walkway to the brick 1908 hall, which keeps its two-story brick buttresses and barrel-vaulted roof (Register form). The rooms are seen only on the guided tour.',
  'Built for a state legislature that met in it twice and left.',
  'Guthrie Scottish Rite, on Capitol Park off East Oklahoma Avenue. Guided tours only, $10 a person, at 10 a.m. Monday to Thursday, none on federal holidays or on days the temple is booked for private events; closed every Friday to Sunday. Its own page, read November 19, 2026, asks parties over ten to call ahead. Parking not checked.',
  [W('Scottish Rite Temple (Guthrie, Oklahoma)'),['Guthrie Scottish Rite: tours','https://guthriescottishrite.org/'],F('87000503')],brick='some',hours='Guided tour 10 a.m. Monday to Thursday, $10 (not federal holidays or private-event days); closed Friday to Sunday'),
N('state-capital-publishing-guthrie','State Capital Publishing Company Building','Guthrie','ok','civic','standing',35.87678,-97.42796,'exact','view','drive','','1902',
  'Frank Greer\'s State Capital, the first daily paper in what is now Oklahoma, moved into a brick building on this corner in 1890. That building burned in March 1902; Joseph Foucart designed this one, its cornerstone laid on August 7 and the building finished by October 14 of the same year. The press closed in 1974 and the Oklahoma Historical Society ran it as a printing museum until 2012, when it shut for lack of money. In June 2024 the society deeded it to the Guthrie Tomorrow Coalition, which is restoring it as the State Capital Publishing Museum.',
  'Red brick, three stories over a full basement, 50 by 140 feet, with the company\'s name painted along the parapet (2015 photograph). The 1973 Register form found the linotypes, cylinder and platen presses, ruling machines and paper cutters still in place (one cutter survived the 1902 fire); a volunteer has since restored a Challenge galley press from the basement. Whether the building opens on set days was not found: look from the street.',
  'A whole printing plant left where it stopped.',
  'Owned by the Guthrie Tomorrow Coalition, which runs it as the State Capital Publishing Museum, 301 West Harrison Avenue (publishingmuseum.org, read November 19, 2026, gave no opening hours). Street parking downtown, not checked.',
  [W('Co-operative Publishing Company Building'),['Oklahoma Historical Society: the campaign to preserve it','https://okhistory.org/learn/publishingmuseum'],['State Capital Publishing Museum','https://www.publishingmuseum.org/'],['OMES: the 2015 request for proposals','https://content.govdelivery.com/accounts/OKOMES/bulletins/f88ae4'],F('73001564')],brick='yes'),
N('guthrie-santa-fe-depot','Guthrie Santa Fe Depot','Guthrie','ok','rail','standing',35.8776,-97.42977,'site','view','drive','stations','1903',
  'Guthrie began in 1887 as a railroad stop called Deer Creek. The present depot was built in 1903, a red brick station 185 feet long with a two-story center and one-story wings, unlike the frame depots of its day. It held the waiting rooms, mail and express rooms and a Harvey House restaurant, whose waitresses lived upstairs. Passenger trains stopped until the Lone Star was dropped in October 1979.',
  'The long red brick depot on the east side of the tracks. A 2018 Waymarking visit found a restaurant and event centre in it with a small Harvey House display; its present use was not checked.',
  '','Beside the working BNSF main line: stay off the tracks. The building\'s owner and present use were not checked, so treat it as view from the street.',
  [W('Guthrie station'),['HMdb: Santa Fe Depot marker','https://www.hmdb.org/m.asp?m=141930'],['Waymarking: Santa Fe Depot (2018)','https://www.waymarking.com/waymarks/WMABAH_Santa_Fe_Depot_Guthrie_OK']],brick='yes'),
N('frontier-drugstore-museum-guthrie','Oklahoma Frontier Drugstore Museum (Gaffney Building)','Guthrie','ok','civic','standing',35.87827,-97.4269,'exact','open','drive','','1890',
  'The Gaffney Building of 1890, one of the contributing buildings of the Guthrie Historic District, has housed the Oklahoma Frontier Drugstore Museum since 1992. The museum, run by the Oklahoma Pharmacy Heritage Foundation, keeps the tools, bottles and papers of frontier pharmacies and doctors; an apothecary garden beside it opened in 2006.',
  'A territorial-era storefront; inside, old drugstore fittings and bottles, many still holding their medicines, and visitors may handle most exhibits (museum page). The garden is next door.',
  '','214 West Oklahoma Avenue. The museum\'s own pages, read November 19, 2026, give no opening hours; call before going. Public toilets in the Guthrie Pavilion by the garden.',
  [W('Oklahoma Frontier Drug Store Museum'),['The museum: about','https://drugmuseum.org/ABOUT.html'],W('Guthrie Historic District (Guthrie, Oklahoma)')],brick='?',hours='?'),
N('pollard-theatre-guthrie','Pollard Theatre (Patterson Building)','Guthrie','ok','civic','standing',35.87727,-97.42633,'exact','open','drive','','1901',
  'A brick and native stone building put up in 1901 as the Patterson Furniture Store, which also served as the town\'s funeral parlour (the district list gives 1903). George Pollard made it a vaudeville and silent-film house in 1919; in 1929 A. R. Powell rebuilt it for talkies as the Melba, and his family ran it until 1984. The Guthrie Arts and Humanities Council restored it for live theatre under the Pollard name, and the Pollard Theatre Company has played here since 1987.',
  'The Romanesque Revival front at 120–122 West Harrison. Inside is a working theatre with a 30-foot proscenium stage; what survives of the 1901 store or the 1929 Melba inside was not checked.',
  '','A working theatre, seen by going to a performance. Hours are show times: see the theatre\'s page.',
  [['The Pollard Theatre: history','https://thepollard.org/history/'],W('Guthrie Historic District (Guthrie, Oklahoma)')],conf='mixed',brick='?',hours='?'),
N('excelsior-library-guthrie','Excelsior Library','Guthrie','ok','civic','standing',35.875046,-97.42793,'exact','view','drive','','1955',
  'In 1908 Judith Carter Horton started the Excelsior Library, believed to be the first library for African Americans in Oklahoma, after her husband was turned away from the Carnegie Library. The city built this building for it under a 1954 bond issue, and it opened in 1955 in what was then a Black neighbourhood south of downtown. The Register listed it in 2016; it stood empty then, and in 2025 its foundation was asking for help to restore it.',
  'A one-story brick building of the 1950s with an angled roof over the entry, held on three columns. The Register form says the inside keeps its original layout, with a stage and the librarian\'s office window.',
  'The building that followed Oklahoma\'s first Black library.',
  '323 South 2nd Street. Not open: look from the street. Owner not checked; the Excelsior Library Foundation leads the restoration.',
  [F('16000087'),['News 9: restoration appeal (2025)','https://www.news9.com/story/67af256a8603fe928bd447d2/oklahoma-s-first-black-library-needs-help-being-restored']],brick='?'),
N('benedictine-heights-hospital','Benedictine Heights Hospital','Guthrie','ok','inst','standing',35.88144,-97.44905,'exact','view','drive','','1926–1948',
  'A five-story hospital begun in 1926 by the Methodist Episcopal Conference, stalled by the Depression and finished in 1948 by Benedictine Sisters. Later run as Logan County Memorial Hospital, it was replaced by a new hospital in 1978 and stood empty for nearly four decades. It was listed on the National Register and then turned into the Villas of Benedictine Pointe, apartments for people 62 and older.',
  'An L-shaped Classical Revival block of brick with limestone trim, with "LOGAN COUNTY MEMORIAL HOSPITAL" lettered over the stone entrance (Register form). It is now housing.',
  '','Apartments for seniors, north of West Warner Avenue at North 19th Street: look from the street only.',
  [F('100001869'),['Guthrie News Page: conversion plans','https://guthrienewspage.com/abandoned-guthrie-hospital-to-be-converted-into-senior-living-center'],['405 Magazine: Guthrie\'s Benedictine revival','https://www.405magazine.com/guthries-benedictine-revival/']],brick='?'),
N('guthrie-armory','Guthrie Armory','Guthrie','ok','civic','standing',35.88342,-97.41678,'site','view','drive','','1935–1937',
  'A National Guard armory built by the Works Progress Administration between 1935 and 1937, one of many WPA armories in Oklahoma. It was listed on the National Register in 1994. Present use and owner were not found.',
  'Roughly cut sandstone, quarried on the site, laid in irregular courses by local unskilled labour, with Art Deco recessed stonework and pilasters rising to a stepped parapet; a cornerstone reads State Armory, built by the Works Progress Administration (Waymarking description). Interior not checked.',
  '','Look from the street; owner and use not checked. The Register form is not on line at NPGallery.',
  [['Waymarking: Guthrie Armory','https://www.waymarking.com/waymarks/WMFC06_Guthrie_Armory_Guthrie_OK']],conf='mixed',brick='no'),
N('summit-view-cemetery-guthrie','Summit View Cemetery and Boot Hill','Guthrie','ok','burial','standing',35.89546,-97.40743,'area','public','drive','cemeteries','1890',
  'A cemetery set up by citizens around 1890 and owned by the City of Guthrie since 1915. Territorial governors Cassius Barnes and Robert Martin and Chief Justice Frank Dale lie here. Its Boot Hill section holds outlaws, among them Bill Doolin of the Doolin gang, Richard "Little Dick" West, Charlie Pierce, Bert Casey and Elmer McCurdy, a robber killed in 1911 whose body was shown at carnivals for years before it was brought here.',
  'The Boot Hill graves of Doolin and McCurdy. Where in the cemetery Boot Hill is was not found: ask at the office.',
  'Where the sideshow mummy was finally buried.',
  'City cemetery; office at 1808 North Pine Street, (405) 282-2773. Visiting hours were not given on the city\'s page. The pin is the office address, not Boot Hill.',
  [['City of Guthrie: cemetery','https://www.cityofguthrie.com/cemetery'],W('Summit View Cemetery')],brick='no'),
N('guthrie-historic-district','Guthrie Historic District','Guthrie','ok','town','standing',35.8781,-97.4254,'area','public','walk','','1889–1910',
  'Guthrie filled with about 10,000 people on the day of the Land Run, April 22, 1889, became the capital of Oklahoma Territory and, in 1907, the first state capital, until voters moved it to Oklahoma City in 1910. Trade then drained away and the downtown changed little. Its commercial core, built mostly between 1889 and 1910 and much of it to Joseph Foucart\'s designs, became a National Historic Landmark district in 1999.',
  'Block after block of red brick 1890s fronts on Oklahoma and Harrison avenues and Second Street: the Victor Block (1893), the Gray Brothers and DeSteiguer buildings attributed to Foucart, the Foucart Building of 1891 with Gothic touches, the Bonfils and De Ford buildings (1890), and Baxter and Cammack\'s livery stable on South Second.',
  'A territorial capital left almost as it was when the capital left.',
  'Public city streets (the district is the downtown); park on the street. Most buildings are shops and offices.',
  [W('Guthrie Historic District (Guthrie, Oklahoma)'),W('Guthrie, Oklahoma')],brick='yes'),
N('ozark-trails-obelisk-langston','Ozark Trails–Indian Meridian Obelisk','Langston','ok','landmark','standing',35.94211,-97.24706,'site','public','drive','','1922',
  'A concrete obelisk about 21 feet tall, put up in 1922 on the Ozark Trails, the road network William "Coin" Harvey promoted to bring motorists toward his resort at Monte Ne, Arkansas. It is one of only two Ozark Trails monuments left in Oklahoma; the other is near Stroud.',
  'The obelisk on its cube base, standing in the middle of the junction of Logan Avenue and East Washington Avenue, with a later eight-foot brick edging round the base to keep cars off.',
  'A 1920s highway marker standing in the middle of a road.',
  'In a public street on the east side of Langston, less than a mile south of Highway 33. It stands in the roadway: look from the side of the road and mind traffic.',
  [F('100001074')],brick='some'),
N('mulhall-methodist-church','Mulhall United Methodist Church','Mulhall','ok','worship','standing',36.063333,-97.403611,'area','view','drive','','1894',
  'Finished early in 1894, five years after the Land Run, at a cost of about $3,000. The 1984 Register form called it the oldest church building still intact in north central Oklahoma and the best Gothic Revival church there, with weekly services still held.',
  'Coursed red sandstone quarried west of Mulhall below, white fish-scale shingles above; pointed-arch windows, wagon-wheel round windows in every gable, a round stained-glass window in the rear gable and a tent-roofed belfry. A cedar planted by members in 1902 stands by it; a concrete-block classroom wing of 1961 is at the back. Interior not checked.',
  '','An active church, as of the 1984 form; service times were not found. Look from the street. The pin is the Register point and may be off the building: on the aerial it is on an open lot.',
  [F('84003145')],brick='no'),
N('oklahoma-state-bank-mulhall','Oklahoma State Bank (Mulhall)','Mulhall','ok','civic','standing',36.06485,-97.40706,'area','view','drive','','1908',
  'Mulhall\'s first bank, founded and built in 1908 on the northwest corner of Baty and Main. The bank moved to a new building in 1982 and kept the old one in good order.',
  'A two-story bank of native sandstone with a cut-away corner entrance between sandstone pilasters, round arches over every door and window, and a pressed-tin cornice the Register form singles out. Interior not checked.',
  '','Look from the street; present owner and use not checked. The pin is the street corner, not the building.',
  [F('84003146')],brick='no'),
N('marshall-methodist-church','Marshall Methodist Church','Marshall','ok','worship','standing',36.1528,-97.62283,'site','view','drive','','1898',
  'A Carpenter Gothic church built in 1898 in the first town of Marshall and moved in 1902 when the whole town moved near the Santa Fe depot. The 1984 Register form calls it the only original church left in Marshall and its best example of the style.',
  'Clapboard walls, pointed-arch windows with simple tracery under wooden hood moulds, a three-sided bay at the east end and a tent-roofed bell tower at the northwest corner. Interior not checked.',
  '','Owned by the United Methodist Church in 1984; whether it still holds services was not checked. Look from the street.',
  [F('84003143')],brick='no'),
N('angie-debo-house','Angie Debo House','Marshall','ok','landmark','standing',36.155,-97.623056,'area','view','drive','','1927',
  'Built in 1927 by her brother Edwin for the historian Angie Debo (1890–1988), whose parents lived in it with her and after whose deaths it was hers alone. Her book And Still the Waters Run, on the corruption of allotment among the Five Civilized Tribes, named names; Princeton University Press published it, much revised, in 1940. The house stood empty when it was listed in 1996.',
  'A one-story weatherboard bungalow with a full-width porch and two red brick chimneys; its south side faces Market Street.',
  'The home of the historian who named the men who took the tribes\' land.',
  'Private; look from the street. Owner not checked. The pin is the Register list point, not checked against an address.',
  [F('96000379')],conf='mixed',brick='some'),
]
